pub struct Mw {
    pub name: &'static str,
    pub x: &'static [f64],
    pub y: &'static [f64],
    pub tail: u8,
    pub exact: bool,
    /// None where Origin shows no result (a group of one).
    pub origin: Option<MwOrigin>,
}
pub struct MwOrigin {
    pub rank_sum1: f64,
    pub rank_sum2: f64,
    pub u: f64,
    pub z: f64,
    pub p: f64,
    pub p2: f64,
}
pub struct Sr {
    pub name: &'static str,
    pub x: &'static [f64],
    pub y: &'static [f64],
    pub median: f64,
    pub tail: u8,
    pub t: f64,
    pub z: f64,
    pub p_exact: f64,
    pub p_asym: f64,
}
pub struct Kw {
    pub name: &'static str,
    pub groups: &'static [&'static [f64]],
    pub n: &'static [f64],
    pub mean_rank: &'static [f64],
    pub rank_sum: &'static [f64],
    pub chi2: f64,
    pub df: f64,
    pub p: f64,
}
pub struct Cc {
    pub name: &'static str,
    pub cols: &'static [&'static [f64]],
    pub listwise: bool,
    /// Row-major k x k matrices of r and p for Pearson, Spearman and Kendall.
    pub r: [&'static [f64]; 3],
    pub p: [&'static [f64]; 3],
}

